export const MONSTERS_BY_TIER = {
  minion: DND_MONSTERS.filter((m) => m.tier === 'minion'),
  elite: DND_MONSTERS.filter((m) => m.tier === 'elite'),
  boss: DND_MONSTERS.filter((m) => m.tier === 'boss'),
  mythic: DND_MONSTERS.filter((m) => m.tier === 'mythic'),
};

export function getRandomMonster(tier?: 'minion' | 'elite' | 'boss' | 'mythic'): DndMonster {
  if (tier) {
    const pool = MONSTERS_BY_TIER[tier];
    return pool[Math.floor(Math.random() * pool.length)];
  }
  return DND_MONSTERS[Math.floor(Math.random() * DND_MONSTERS.length)];
}
